<template><AppShell tab="home"><view class="home-head"><view class="row between"><view><text class="brand">{{site?.brand||'困困'}}<text class="brand-dot">·</text></text><text class="tagline">{{site?.tagline||'地铁逃生，玩家道具集市'}}</text></view><!-- #ifdef H5 --><view class="mini-capsule">•••　│　⊙</view><!-- #endif --></view><view class="search section" @click="go('market/index')"><AppIcon class="app-icon" name="search" :size="18" /><text class="muted">{{site?.searchPlaceholder||'搜装备、密钥与游戏道具'}}</text></view></view><view class="pad home-content"><swiper class="hero-swiper" :indicator-dots="banners.length>1" circular :autoplay="banners.length>1" :interval="6000"><swiper-item v-for="banner in banners" :key="banner.image"><view class="hero-image-link" role="button" :aria-label="banner.label" @click="banner.target?openContentTarget(banner.target):go(banner.path,banner.params)"><image class="hero-image" :src="banner.image" mode="aspectFill" /></view></swiper-item></swiper><button v-if="bannerError" class="ui-button muted tiny" @click="loadBanners">活动加载失败，点击重试</button><view class="shortcuts"><button class="ui-button" v-for="category in categories" :key="category" @click="go('market/index',{itemCategory:category})"><GameArt variant="shortcut" :game="'和平精英'" /><text>{{category}}</text></button><button class="ui-button" @click="go('hall/index')"><view class="shortcut-hall"><AppIcon class="app-icon" name="clipboard" :size="32" /></view><text>求购广场</text></button></view><view class="section-heading section"><text class="section-title">{{site?.recommendedTitle||'人气推荐'}}</text><button class="ui-button section-more" @click="go('market/index')">查看更多<AppIcon class="app-icon" name="chevron" :size="12" /></button></view><StateView :loading="loading" :error="error" :count="items.length" title="道具正在陆续上架" description="也可以发布求购，与其他玩家沟通" @retry="load()" /><ServiceCard v-for="item in items.slice(0,3)" :key="item.id" :item="item" horizontal /><view class="section-heading section"><text class="section-title">{{site?.discoverTitle||'发现好道具'}}</text><text class="muted tiny">{{site?.discoverSubtitle||'更多选择，刚好适合你'}}</text></view><view class="service-grid"><ServiceCard v-for="item in items.slice(3)" :key="item.id" :item="item" /></view></view></AppShell></template>
<script setup>
import {ref} from 'vue';import {onShow} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import AppIcon from '../../components/AppIcon.vue';import GameArt from '../../components/GameArt.vue';import ServiceCard from '../../components/ServiceCard.vue';import StateView from '../../components/StateView.vue';import {useList} from '../../lib/useList';import {go,loadMe,loadConfig,request} from '../../lib/api'
import {rewardImage} from '../../lib/rewards'
import {loadSite,contentImage,openContentTarget} from '../../lib/content'
import {HOME_BANNERS} from '../../lib/homeBanners'
const site=ref(null)
const categories=['密钥','传世武器','护甲'],banners=ref(HOME_BANNERS),bannerError=ref('');let bannerVersion=0
const {items,loading,error,load}=useList('/boost/listings',()=>({kind:'SERVICE',sort:'sales'}));onShow(()=>{load();loadMe().catch(()=>{});loadBanners()})
async function loadBanners(){const v=++bannerVersion;bannerError.value='';try{const config=await loadSite();if(v!==bannerVersion)return;site.value=config;if(config){banners.value=config.banners.map(b=>({...b,image:contentImage(b.image)}));return}if(!(await loadConfig()).rewardsEnabled)return;const r=await request('/boost/rewards/activities');if(v===bannerVersion)banners.value=[...HOME_BANNERS,...r.items.filter(a=>rewardImage(a.cover)).map(a=>({image:rewardImage(a.cover),path:'rewards/activity',params:{id:a.id},label:'打开'+a.title}))]}catch(e){if(v===bannerVersion)bannerError.value=e.message}}
</script>
<style scoped>.home-head{background:#fff;padding:18px 18px 12px}.brand{font-size:30px;line-height:1.2;font-weight:900;letter-spacing:-1.5px;display:block}.brand-dot{color:#f4d400;font-size:42px;line-height:24px}.tagline{font-size:11px;color:#8d8d96;letter-spacing:1px;margin-top:5px;display:block}.mini-capsule{display:flex;align-items:center;height:29px;padding:0 12px;border:1px solid #ececf0;border-radius:20px;font-weight:700;font-size:12px}.home-head .section{margin-top:14px}.home-content{padding-top:6px;background:#fff}.hero-swiper{height:174px;border-radius:16px;overflow:hidden}.hero{height:100%;background:#ffe433;position:relative;overflow:hidden;border-radius:16px}.hero-copy{position:relative;padding:20px 16px;max-width:78%}.hero-eyebrow{font-size:8px;letter-spacing:2px;font-weight:700;display:block;margin-bottom:5px}.hero-title{font-size:25px;font-weight:900;letter-spacing:-1.3px;display:block;white-space:nowrap}.hero-sub{font-size:11px;display:block;margin:3px 0 12px}.hero-button{display:inline-flex;align-items:center;gap:8px;background:#191919;color:#fff;padding:5px 12px;border-radius:20px;font-size:11px;font-weight:600}.hero-button .app-icon{filter:invert(1)}.shortcuts{display:flex;justify-content:space-between;padding:20px 7px 16px;gap:10px}.shortcuts button{display:flex;flex-direction:column;align-items:center;gap:8px;font-size:12px;font-weight:600}.shortcuts .game-art,.shortcut-hall{width:57px;height:57px;border-radius:16px}.shortcut-hall{background:#ffe433;display:flex;align-items:center;justify-content:center}.trust-strip{display:flex;justify-content:space-between;font-size:11px;color:#8b7b40;padding:0 9px 10px;border-bottom:1px solid #eae9e5}.editorial-banner{display:flex;align-items:center;justify-content:space-between;border-radius:14px;background:#eeedf8;padding:18px 15px;margin-top:18px}.editorial-banner text{display:block}.editorial-banner .bold{font-size:14px;margin-bottom:5px}.round-arrow{width:35px;height:35px;background:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center}.home-head{padding:14px 16px 10px}.brand{font-size:27px;letter-spacing:-1px}.brand-dot{font-size:32px}.tagline{margin-top:2px}.home-head .section{margin-top:10px}.hero-swiper{height:172px;border-radius:12px}.hero-copy{padding:30px 16px;max-width:85%}.hero-title{font-size:26px;letter-spacing:-1px}.hero-sub{margin:3px 0 12px}.shortcuts{padding:14px 4px 0;gap:6px}.shortcuts button{gap:5px;font-size:11px;min-width:56px}.shortcut-hall{width:56px;height:56px;border-radius:14px}.home-content>.section-heading{margin-top:18px;margin-bottom:8px}.editorial-banner{margin-top:16px;padding:14px}.hero-button{min-height:30px}.hero-copy{z-index:2}.hero-arrow{color:#fff;font-size:16px;line-height:1}@media(max-width:350px){.hero-title{font-size:22px}.hero-copy{padding-left:12px}}.hero-copy{max-width:calc(100% - 168px);box-sizing:border-box;padding:18px 12px}.hero-title{font-size:24px;line-height:1.2;white-space:normal}@media(max-width:350px){.hero-title{font-size:20px}}.hero-title>text{display:block}.hero-image-link,.hero-image{display:block;width:100%;height:100%}.hero-image-link{overflow:hidden;border-radius:12px}.hero-swiper{height:172px}</style>



